import re

import django.db.models.deletion
from django.db import migrations, models

# Las notas que la pantalla de pago escribe desde el Sprint 4: "Compra #12 con ..." en
# la compra y "Conversión para pagar la compra #12" en la venta de conversión.
ORDER_IN_NOTE = re.compile(r"^(?:Compra #|Conversión para pagar la compra #)(\d+)\b")


def link_existing_movements(apps, schema_editor):
    """Enlaza los movimientos ya existentes con su compra, a partir de la nota."""
    WalletTransaction = apps.get_model("core", "WalletTransaction")
    PurchaseOrder = apps.get_model("core", "PurchaseOrder")
    for movement in WalletTransaction.objects.filter(purchase_order__isnull=True, note__icontains="compra #"):
        match = ORDER_IN_NOTE.match(movement.note)
        if not match:
            continue
        # Sólo una orden de la misma billetera: la nota es texto libre, no una referencia.
        order = PurchaseOrder.objects.filter(pk=int(match.group(1)), wallet_id=movement.wallet_id).first()
        if order is not None:
            movement.purchase_order = order
            movement.save(update_fields=["purchase_order"])


class Migration(migrations.Migration):

    dependencies = [
        ('core', '0010_invoice'),
    ]

    operations = [
        migrations.AddField(
            model_name='wallettransaction',
            name='purchase_order',
            field=models.ForeignKey(blank=True, null=True, on_delete=django.db.models.deletion.SET_NULL, related_name='wallet_transactions', to='core.purchaseorder'),
        ),
        migrations.RunPython(link_existing_movements, migrations.RunPython.noop),
    ]
